function navHref(viewKey){return `#${encodeURIComponent(viewKey)}`}
function upgradeNavLinks(){
  $$('.nav button[onclick*="go("]').forEach(btn=>{
    if(btn.dataset.v340Link==='1')return;
    const oc=btn.getAttribute('onclick')||'',m=oc.match(/go\(['"]([^'"]+)['"]\)/);if(!m)return;
    const a=document.createElement('a');a.href=navHref(m[1]);a.className=(btn.className?btn.className+' ':'')+'v340-nav-link';a.innerHTML=btn.innerHTML;a.title=btn.title||'';a.dataset.v340Link='1';a.dataset.navKey=m[1];
    a.addEventListener('click',ev=>{if(ev.button!==0||ev.ctrlKey||ev.metaKey||ev.shiftKey||ev.altKey)return;ev.preventDefault();try{history.replaceState(null,'',navHref(m[1]))}catch(_){};try{closeMobileSidebar()}catch(_){};go(m[1])});
    btn.replaceWith(a);
  });
}

function routeFromHash(){
  const raw=decodeURIComponent(String(location.hash||'').replace(/^#/,'')).trim();
  if(!raw)return;
  const a=$(`.nav a.v340-nav-link[data-nav-key="${CSS.escape(raw)}"]`);if(!a)return;
  try{go(raw)}catch(_){ }
}
window.addEventListener('hashchange',()=>setTimeout(routeFromHash,0));
let v340InitialRouteTries=0;const v340InitialRouteTimer=setInterval(()=>{v340InitialRouteTries++;upgradeNavLinks();if(location.hash&&$('.nav a.v340-nav-link')){clearInterval(v340InitialRouteTimer);routeFromHash()}else if(v340InitialRouteTries>40)clearInterval(v340InitialRouteTimer)},100);

function isActionHeader(cell){return /^(actions?|작업|동작)$/i.test(text(cell?.textContent))}
function isProposalHeader(cell){return /accounting proposal|회계 제안/i.test(text(cell?.textContent))}
function enhanceTable(table){
  if(!table)return;const rows=$$('tr',table);if(!rows.length)return;const h=rows[0],hc=[...h.children];let actionIdx=hc.findIndex(isActionHeader),proposalIdx=hc.findIndex(isProposalHeader);
  if(actionIdx>=0){
    const originalCount=hc.length;if(actionIdx!==originalCount-1){for(const row of rows){if(row.children.length===originalCount)row.appendChild(row.children[actionIdx])}proposalIdx=proposalIdx>actionIdx?proposalIdx-1:proposalIdx;actionIdx=originalCount-1}
    table.classList.add('v340-action-table');for(const row of rows){if(row.children.length===originalCount)row.children[actionIdx]?.classList.add('v340-actions-col')}
  }
  if(proposalIdx>=0){for(const row of rows){if(row.children.length>proposalIdx)row.children[proposalIdx]?.classList.add('v340-proposal-col')}}
  table.dataset.v340Table='1';
}
function enhanceTables(){ $$('.table').forEach(enhanceTable) }

function removeRedundantCurrentPageActions(){
  const posting=!!$('#v318PostingBody')||/accounting posting control/i.test(text($('.titlebar h1')?.textContent||$('h2')?.textContent));if(!posting)return;
  $$('button,.btn,a').forEach(el=>{const label=text(el.textContent);if(/^posting control$/i.test(label)&&!/back/i.test(label)){el.remove()}});
}

function removeDateRangeLabels(){
  $$('.v337-date-group>label').forEach(el=>{if(/^(date range|날짜 범위)$/i.test(text(el.textContent)))el.remove()});
}

function cashReceiverSync(root=document){
  const forms=root.matches?.('form')?[root]:$$('form',root);
  for(const f of forms){
    const method=f.elements?.payment_method||f.elements?.method||f.elements?.token_payment_method;if(!method)continue;
    const isCash=text(method.value).toLowerCase()==='cash';for(const name of ['receiver_account_id','token_receiver_account_id']){const input=f.elements?.[name];if(!input)continue;const holder=input.closest('.field')||input.parentElement;if(isCash){if(!input.dataset.v340Required)input.dataset.v340Required=input.required?'1':'0';input.required=false;input.disabled=true;input.value='';if(holder){holder.dataset.v340CashHidden='1';holder.style.display='none'}}else{input.disabled=false;if(input.dataset.v340Required==='1')input.required=true;if(holder?.dataset.v340CashHidden==='1'){holder.style.display='';delete holder.dataset.v340CashHidden}}}
    if(!method.dataset.v340CashWired){method.dataset.v340CashWired='1';method.addEventListener('change',()=>cashReceiverSync(f))}
  }
}

function accountValidation(root=document){
  $$('input[name="account_number"]',root).forEach(i=>{i.inputMode='numeric';i.pattern='[0-9 \\-]{4,40}';i.title='Use numbers, spaces or hyphens only (minimum 4 digits).';if(!i.dataset.v340AccountValidation){i.dataset.v340AccountValidation='1';i.addEventListener('input',()=>{const v=i.value,digits=(v.match(/\d/g)||[]).length;if(v&&(!/^[0-9 -]{4,40}$/.test(v)||digits<4))i.setCustomValidity('Use numbers, spaces or hyphens only, with at least 4 digits.');else i.setCustomValidity('')})}})
}

function upgradeGenericFilterCards(){
  $$('.card').forEach(card=>{
    if(card.dataset.v340FilterCard==='1')return;
    const head=card.querySelector(':scope > .section-title'),heading=head?.querySelector('h2,h3,h4');if(!head||!heading)return;
    if(!/(^|\s)(filters?|필터)$/i.test(text(heading.textContent)))return;
    card.dataset.v340FilterCard='1';card.classList.add('v340-filter-card','v340-filter-collapsed');
    const b=document.createElement('button');b.type='button';b.className='btn small v340-filter-toggle';b.textContent=tr('Show Filters');b.addEventListener('click',()=>{const closed=card.classList.toggle('v340-filter-collapsed');b.textContent=tr(closed?'Show Filters':'Hide Filters')});head.appendChild(b);
  });
}
function protectVerifiedVoidButtons(){
  if(me?.role==='CEO / Owner')return;
  $$('tr,.card,.row,.ps-mini').forEach(scope=>{
    const state=text(scope.textContent);if(!/(Verified|Verified \/ Correct|Accounting Posted|Posted|검증|전기 완료)/i.test(state))return;
    $$('button,a',scope).forEach(btn=>{if(/^void$/i.test(text(btn.textContent))||/^void\s/i.test(text(btn.textContent))){btn.remove()}});
  });
}
