  const assigned=new Set((data.user.assigned_units||[]).map(x=>n(x.id))),scopeUnits=data.user.role==='CEO / Owner'?units:units.filter(x=>assigned.has(n(x.id))),primary=n(data.user.primary_business_unit_id||data.user.business_unit_id),bu=n(scopeBu)||primary||n(scopeUnits[0]?.id);let effective=data.effective;if(bu&&n(effective?.business_unit_id)!==bu)effective=await api(`/api/access/users/${id}/effective?business_unit_id=${bu}`);return {data,catalog,profiles,groups,units,users,scopeUnits,bu,effective};
